static void emit_inter6(const double* re, const double* im, double* out){
  for (long x=0; x<6; x++) for (long y=0; y<6; y++){
    long o = x*48 + y*8;
    emit_inter(re + o, im + o, out + (x*36 + y*6)*2, 6);
  }
}
static void emit_dual6(const double* re, const double* im, double* o1, double* o2){
  for (long x=0; x<6; x++) for (long y=0; y<6; y++){
    long o = x*48 + y*8;
    emit_inter2(re + o, im + o, o1 + (x*36 + y*6)*2, o2 + (x*36 + y*6)*2, 6);
  }
}
void convert_all6(const double* src, double* st, long B){
  for (long v = 0; v < B; v++){
    double* re = st + v*2L*296; double* im = re + 296;
    for (long x=0; x<6; x++) for (long y=0; y<6; y++){
      long o = x*48 + y*8;
      conv_split(src + v*2*216 + (x*36 + y*6)*2, re + o, im + o, 6);
    }
  }
}

void run6(double* st, double* cst, long B, long m, double* out1, double* outm){
  for (long vv=0; vv<B; vv++){
    double* re = st + vv*2L*296;
    double* im = re + 296;
    double* cre = cst + vv*2L*296;
    double* cim = cre + 296;
    for (long it=0; it<m; it++){
      { int sl = 0;
      for (int g=0; g<4; g++){
        zk6_8(re + g*64, im + g*64);
        while ((g+1)*8 >= (sl+1)*6 && sl < 6){
          double* pr = re + sl*48; double* pi = im + sl*48;
          for (int g=0; g<1; g++) colk6(pr + g*8, pi + g*8);
          sl++; }
      }
      zk6_t(re + 256, im + 256);
      while (sl < 6){
        double* pr = re + sl*48; double* pi = im + sl*48;
        for (int g=0; g<1; g++) colk6(pr + g*8, pi + g*8);
        sl++; }
      }
      for (int y=0; y<6; y++) for (int zb=0; zb<1; zb++){ long o = y*8 + zb*8; xek6(re + o, im + o, cre + o, cim + o); }
      if (it==0 && m>1) emit_inter6(re, im, out1 + vv*2L*216);
    }
    if (m==1) emit_dual6(re, im, out1 + vv*2L*216, outm + vv*2L*216);
    else emit_inter6(re, im, outm + vv*2L*216);
  }
}
