  int nt = ((((uintptr_t)out) & 63) == 0) && (8192 % 64 == 0);
  for (; i + 8 <= 512; i += 8){
    __m512d R[8], I[8];
    for (int k=0; k<8; k++){
      R[k] = _mm512_load_pd(re + (i+k)*8);
      I[k] = _mm512_load_pd(im + (i+k)*8);
    }
    tr8(R); tr8(I);
    if (nt) for (int l=0; l<8; l++){
      _mm512_stream_pd(out + l*1024 + 2*i,     _mm512_permutex2var_pd(R[l], IL, I[l]));
      _mm512_stream_pd(out + l*1024 + 2*i + 8, _mm512_permutex2var_pd(R[l], IH, I[l]));
    }
    else for (int l=0; l<8; l++){
      _mm512_storeu_pd(out + l*1024 + 2*i,     _mm512_permutex2var_pd(R[l], IL, I[l]));
      _mm512_storeu_pd(out + l*1024 + 2*i + 8, _mm512_permutex2var_pd(R[l], IH, I[l]));
    }
  }
  if (nt) _mm_sfence();
