static void emit_inter36(const double* re, const double* im, double* out){
  for (long x=0; x<36; x++) for (long y=0; y<36; y++){
    long o = x*1440 + y*40;
    emit_inter(re + o, im + o, out + (x*1296 + y*36)*2, 36);
  }
}
static void emit_dual36(const double* re, const double* im, double* o1, double* o2){
  for (long x=0; x<36; x++) for (long y=0; y<36; y++){
    long o = x*1440 + y*40;
    emit_inter2(re + o, im + o, o1 + (x*1296 + y*36)*2, o2 + (x*1296 + y*36)*2, 36);
  }
}
void convert_all36(const double* src, double* st, long B){
  for (long v = 0; v < B; v++){
    double* re = st + v*2L*51848; double* im = re + 51848;
    for (long x=0; x<36; x++) for (long y=0; y<36; y++){
      long o = x*1440 + y*40;
      conv_split(src + v*2*46656 + (x*1296 + y*36)*2, re + o, im + o, 36);
    }
  }
}

void run36(double* st, double* cst, long B, long m, double* out1, double* outm){
  for (long vv=0; vv<B; vv++){
    double* re = st + vv*2L*51848;
    double* im = re + 51848;
    double* cre = cst + vv*2L*51848;
    double* cim = cre + 51848;
    for (long it=0; it<m; it++){
      { int sl = 0;
      for (int g=0; g<162; g++){
        zk36_8(re + g*320, im + g*320);
        while ((g+1)*8 >= (sl+1)*36 && sl < 36){
          double* pr = re + sl*1440; double* pi = im + sl*1440;
          for (int g=0; g<5; g++) colk36(pr + g*8, pi + g*8);
          sl++; }
      }
      while (sl < 36){
        double* pr = re + sl*1440; double* pi = im + sl*1440;
        for (int g=0; g<5; g++) colk36(pr + g*8, pi + g*8);
        sl++; }
      }
      for (int y=0; y<36; y++) for (int zb=0; zb<5; zb++){ long o = y*40 + zb*8; xek36(re + o, im + o, cre + o, cim + o); }
      if (it==0 && m>1) emit_inter36(re, im, out1 + vv*2L*46656);
    }
    if (m==1) emit_dual36(re, im, out1 + vv*2L*46656, outm + vv*2L*46656);
    else emit_inter36(re, im, outm + vv*2L*46656);
  }
}

void bz36(double* st, long reps){
  double* re = st; double* im = re + 51848;
  for (long r=0;r<reps;r++){
    for (int g=0; g<162; g++) zk36_8(re + g*320, im + g*320);
  }
}

void by36(double* st, long reps){
  double* re = st; double* im = re + 51848;
  for (long r=0;r<reps;r++) for (int sl=0; sl<36; sl++){
    double* pr = re + sl*1440; double* pi = im + sl*1440;
    for (int g=0; g<5; g++) colk36(pr + g*8, pi + g*8);
  }
}

void bx36(double* st, double* cst, long reps){
  double* re = st; double* im = re + 51848;
  double* cre = cst; double* cim = cre + 51848;
  for (long r=0;r<reps;r++){
    for (int y=0; y<36; y++) for (int zb=0; zb<5; zb++){ long o = y*40 + zb*8; xek36(re + o, im + o, cre + o, cim + o); }
  }
}
